/*
Definition of singly linked list:
struct ListNode
{
    int val;
    ListNode *next;
    ListNode()
    {
        val = 0;
        next = NULL;
    }
    ListNode(int data1)
    {
        val = data1;
        next = NULL;
    }
    ListNode(int data1, ListNode *next1)
    {
        val = data1;
        next = next1;
    }
};
*/

class Solution {
   public:
    ListNode* Reverse(ListNode* head) {
        ListNode* prev = nullptr;
        ListNode* curr = head;
        while (curr) {
            ListNode* nxt = curr->next;
            curr->next = prev;
            prev = curr;
            curr = nxt;
        }
        return prev;
    }
    int length(ListNode* head) {
        ListNode* curr = head;
        int cnt = 0;
        while (curr) {
            curr = curr->next;
            cnt++;
        }
        return cnt;
    }
    pair<ListNode*, ListNode*> reversesplit(ListNode* low, ListNode* high) {
        ListNode* prev = nullptr;
        ListNode* curr = low;
        ListNode* tail = low;

        while (curr != high) {
            ListNode* nxt = curr->next;
            curr->next = prev;
            prev = curr;
            curr = nxt;
        }
        return {prev, tail};
    }
    ListNode* rotateRight(ListNode* head, int k) {
        if(head==nullptr || head->next==nullptr || k==0){
            return head;
        }
        k = k % length(head);
        if(k==0) return head;
        head = Reverse(head);
        ListNode* low = head;
        ListNode* high = head;
        ListNode* tail = nullptr;
        while (k--) {
            high = high->next;
        }
        pair<ListNode*, ListNode*> p = reversesplit(low, high);
        if (tail == nullptr) {
            head = p.first;
            tail = p.second;
        }
        low = high;
        high = nullptr;
        p = reversesplit(low, high);
        tail->next = p.first;
        return head;
    }
};
